// Verifies the HMAC signature LendLoop sends on every event.
// Fails closed: no raw body or bad signature -> workflow error (lands in the
// error handler), nothing is notified.
const crypto = require("crypto");
const full = $input.first();
const item = full.json;
// Webhook node's "Raw Body" option delivers the raw bytes base64-encoded in binary.data.data
const raw = full.binary?.data?.data
  ? Buffer.from(full.binary.data.data, "base64").toString("utf8")
  : undefined;
const ts = item.headers?.["x-lendloop-timestamp"];
const sig = item.headers?.["x-lendloop-signature"];
if (!raw || !ts || !sig) {
  throw new Error(
    "Missing raw body or X-Lendloop-* signature headers. " +
      `keys=${Object.keys(item).join(",")} headers=${JSON.stringify(item.headers)}`
  );
}
const expected =
  "v1=" +
  crypto
    .createHmac("sha256", $env.N8N_WEBHOOK_SECRET)
    .update(`${ts}.${raw}`)
    .digest("hex");
const a = Buffer.from(expected);
const b = Buffer.from(sig);
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
  throw new Error("Invalid webhook signature");
}
if (Math.abs(Date.now() / 1000 - Number(ts)) > 300) {
  throw new Error("Stale webhook timestamp");
}
return $input.all();

// Mock notification - swap this node for Email/Slack/Discord in n8n.
const d = $input.first().json.body ?? $input.first().json;
const { event, recipient, listing, counterparty, startDate, endDate } = d;
const line =
  `[notify] ${event} -> ${recipient?.email ?? recipient?.name ?? "unknown"}: ` +
  `${counterparty?.name ?? "Someone"} / ${listing?.name ?? "a tool"} (${startDate} -> ${endDate})`;
console.log(line);
return [{ json: { delivered: true, notification: line } }];
